import{d as p,C as s,o as g,c as d,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第三十五章","description":"《正易心法》第三十五章——大衍七七，其一不用：大衍五十、其用四十九、挂一不用；「一」是数之宗本，宗本不当用，用则复乱——以八喻明「不动之理」。","frontmatter":{"title":"正易心法·第三十五章","description":"《正易心法》第三十五章——大衍七七，其一不用：大衍五十、其用四十九、挂一不用；「一」是数之宗本，宗本不当用，用则复乱——以八喻明「不动之理」。","category":"guide","aliases":["正易心法第三十五章","大衍七七其一不用","一者数之宗本"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-35.md","filePath":"yijing/zheng-yi-xin-fa/chapter-35.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-35.md"},x=p({...c,setup(u){const i=[{id:"z35-01",label:"一、大衍七七",showLabel:!0,sentences:[[{text:"大衍",glossary:"dayan"},"七七，其一不用。凡得一数，理自不动。"]],note:["大衍之数是七七（四十九），其中一个不使用。凡是得到「一」这个数的，道理上自然是不动的。（**「七七」不是随意的写法**：麻衣用 7×7 代替「四十九」，是在**强调它的结构**——七是少阳之数，七七即阳数自乘，**49 由此是一个「自足」的数，不需要外加那个「一」。**）"]},{id:"z35-02",label:"二、不用之义",showLabel:!0,sentences:[["大衍之数五十。其用四十九，",{text:"挂一",glossary:"guayi"},"而不用。不用之义，学者徒知一为太极不动之数，而不知",{text:"义实落处",glossary:"yishiLuochu"},"也。"]],note:["大衍之数是五十，其中用四十九，挂一而不用。关于这个「不用」的意义，学者只知道「一」是太极不动之数，却不知道这个意义真正落脚在哪里。（**麻衣的批评很准**：知道「一不动」是**结论**，不知道**为什么**不动——**「不知义实落处」正是全书一贯的方法论批评**：任何说法都要有它的落处。）"]},{id:"z35-03",label:"三、一者数之宗本",showLabel:!0,sentences:[["何则？一者，数之",{text:"宗本",glossary:"zongben"},"也。凡物之理，无所宗本则乱，有宗本焉，则不当用，用则复乱矣。"]],note:["为什么呢？一，是数的宗主和根本。万物之理，没有宗本就会混乱；有了宗本，就不应当被使用，一旦使用，就又会混乱了。（**这是本章的核心命题，也是全书的工夫论之一**：**宗本的功能就是「不参与」——「不参与」才是它最大的参与。** 它的价值在于「不做什么」，而非「做了什么」。）"]},{id:"z35-04",label:"四、八喻明不动",showLabel:!0,sentences:[["且如轮之运，而中则止。如",{text:"辖",glossary:"xia"},"之行，而大者后。如网之有",{text:"纲",glossary:"gang"},"，而纲则提之。如器之有",{text:"柄",glossary:"bing"},"，而柄则执之。如元首在上，手足为之举。如大将居中，而士卒为之",{text:"役",glossary:"yi"},"。如君无为，而臣有为。如贤者尊，而能者使。"]],note:["就好比：轮子转动，轴心静止；车辖运行，大头在后（固定不动）；网有纲绳，纲绳提起整张网；器有把柄，执柄掌控整个器具；头在最上，手足为它运动；大将居中，士卒为它效力；君主无为，臣子有为；贤者被尊崇，能者被使用。（**八个比喻，同一个结构：不动的「一」，使动的「多」得以运作。** 末一个「贤者尊，能者使」尤其值得留意——**它不是空间关系，而是价值关系：德为宗本（不动），才为枝末（动）。**）"]},{id:"z35-05",label:"五、宗本主",showLabel:!0,sentences:[["是知凡得一者，宗也，本也，主也，皆有不动之理。"]],note:["由此可知，凡是得到「一」的，就是宗、是本、是主，都有不动的道理。（**「一」的三重身份**：**宗**＝来源（所有数从它派生，它不参与流动）；**本**＝支撑（树根不动，枝叶才能生长）；**主**＝统御（君主不亲自执行，才能总揽全局）。**三者合一，就是「一」的完整定义。**）"]},{id:"z35-06",label:"六、一苟动焉",showLabel:!0,sentences:[["一苟动焉，则其余错乱，而不能有所",{text:"施设",glossary:"shishe"},"者矣。"]],note:["一旦那个「一」动了，其余的就会错乱，无法正常运作了。（**以轮为喻**：轴心静止则轮缘匀速转动；轴心偏移则轮缘抖动偏转。**以君臣为喻**：君守无为则臣各司其职；君亲自为则臣无所适从。**以数为喻**：一不参与演算则四十九蓍草有序分组；一参与演算则失去基准。**这正是《老子》「无为」思想在数理符号中的体现。**）"]}],o=[{id:"dayan",term:"大衍",pinyin:"dà yǎn",meaning:"大的推演。《系辞》「大衍之数五十」，是筮法的总数。"},{id:"guayi",term:"挂一",pinyin:"guà yī",meaning:"悬挂一根，不参与演算。这一根代表太极，是数的宗本。"},{id:"yishiLuochu",term:"义实落处",pinyin:"yì shí luò chù",meaning:"意义真正落脚的地方。麻衣批评学者只知「一不动」的结论，不知其所以然。"},{id:"zongben",term:"宗本",pinyin:"zōng běn",meaning:"宗主与根本。一是所有数的来源，故为宗本；宗本不当用，用则复乱。"},{id:"xia",term:"辖",pinyin:"xiá",meaning:"车轴两端的销子。辖的大头固定不动，小头随轮转动。"},{id:"gang",term:"纲",pinyin:"gāng",meaning:"提网的粗绳。「纲举目张」：一个核心带动全体。"},{id:"bing",term:"柄",pinyin:"bǐng",meaning:"把柄、把手。执柄即掌控整个器具。"},{id:"yi",term:"役",pinyin:"yì",meaning:"效劳、服役。士卒为将帅效力。"},{id:"shishe",term:"施设",pinyin:"shī shè",meaning:"施展、运作。宗本一动，全体皆乱，无法正常运作。"}];return(b,n)=>{const r=s("DaoTextReading"),l=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t("",20)),e(r,{colophon:"大衍七七 · 挂一不用 · 一者宗本 · 理自不动",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第三十五章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"大衍七七",pinyin:["dà","yǎn"],meaning:"麻衣以「七七」（7×7＝49）代「四十九」，强调其为阳数自乘——49 是自足的数，无需外加「一」。"},{term:"挂一不用",pinyin:["guà","yī"],meaning:"悬置一根不参与演算。这一根代表太极，是数的宗本。"},{term:"一者数之宗本",pinyin:["zōng","běn"],meaning:"宗＝来源，本＝支撑，主＝统御。三者合一，即「一」的完整身份。"},{term:"八喻",pinyin:["bā","yù"],meaning:"轮、辖、网、器、元首、大将、君臣、贤能——同一个结构：不动的「一」使动的「多」得以运作。"},{term:"一苟动焉",pinyin:["yī","gǒu"],meaning:"一旦那个「一」动了，其余就错乱而无法运作——《老子》「无为」在数理符号中的体现。"}]}),n[3]||(n[3]=t("",26))])}}});export{m as __pageData,x as default};
